import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        num_test_cases = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(num_test_cases):
        n = int(next(iterator))
        k = int(next(iterator))
        l = int(next(iterator))

        d = []
        for _ in range(n):
            d.append(int(next(iterator)))

        possible = True

        if l >= k:
            for val in d:
                if val > l:
                    possible = False
                    break
            if possible:
                results.append("Yes")
            else:
                results.append("No")
            continue

        current_tide = 0

        for val in d:
            if val > l:
                possible = False
                break

            needed = max(0, val - (l - k))

            if needed > current_tide:
                diff = needed - current_tide
                if diff > k:
                    possible = False
                    break
                current_tide = needed
            elif needed < current_tide:
                current_tide = needed
            else:
                pass

            current_tide += 1

            if current_tide > k:
                current_tide = k - (current_tide - k)

        if possible:
            results.append("Yes")
        else:
            results.append("No")

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
